<template><OperationsFrame title="部门管理">
 <el-form inline v-show="showSearch"><el-form-item label="部门名称"><el-input v-model="keyword" clearable placeholder="请输入部门名称" /></el-form-item><el-form-item label="状态"><el-select v-model="status" clearable style="width:140px"><el-option label="正常" value="0"/><el-option label="停用" value="1"/></el-select></el-form-item><el-button icon="Search" type="primary" @click="load">搜索</el-button><el-button icon="Refresh" @click="keyword='';status='';load()">重置</el-button></el-form>
 <el-row class="mb8"><el-button type="primary" plain icon="Plus" @click="open()">新增</el-button><right-toolbar v-model:showSearch="showSearch" @queryTable="load"/></el-row>
 <el-table v-loading="loading" :data="filtered" row-key="deptId" default-expand-all :tree-props="{children:'children'}"><el-table-column prop="deptName" label="部门名称" min-width="220"/><el-table-column prop="orderNum" label="排序" width="80"/><el-table-column prop="leader" label="负责人" min-width="120"/><el-table-column prop="phone" label="联系电话" min-width="130"/><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.status==='0'?'success':'info'">{{row.status==='0'?'正常':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="230"><template #default="{row}"><el-button link type="primary" icon="Edit" @click="open(row)">修改</el-button><el-button link type="primary" icon="Plus" @click="open(null,row.deptId)">新增</el-button><el-button link type="primary" icon="Delete" @click="remove(row)">删除</el-button></template></el-table-column></el-table>
 <el-dialog v-model="visible" :title="form.deptId?'修改部门':'新增部门'" width="620px" append-to-body class="access-dialog" :close-on-click-modal="false"><el-form ref="formRef" :model="form" :rules="rules" label-width="100px"><el-form-item label="上级部门" prop="parentId"><el-tree-select v-model="form.parentId" :data="parentTree" check-strictly :render-after-expand="false" default-expand-all/></el-form-item><el-form-item label="部门名称" prop="deptName"><el-input v-model="form.deptName" maxlength="30"/></el-form-item><el-form-item label="显示排序" prop="orderNum"><el-input-number v-model="form.orderNum" :min="0" :max="9999"/></el-form-item><el-form-item label="负责人"><el-input v-model="form.leader" maxlength="20"/></el-form-item><el-form-item label="联系电话"><el-input v-model="form.phone" maxlength="11"/></el-form-item><el-form-item label="邮箱"><el-input v-model="form.email" maxlength="50"/></el-form-item><el-form-item label="部门状态" prop="status"><el-radio-group v-model="form.status"><el-radio value="0">正常</el-radio><el-radio value="1">停用</el-radio></el-radio-group></el-form-item></el-form><template #footer><el-button type="primary" :loading="saving" @click="save">确 定</el-button><el-button @click="visible=false">取 消</el-button></template></el-dialog>
</OperationsFrame></template>
<script setup>
import {ref,reactive,computed,onMounted} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import OperationsFrame from '@/views/operations/OperationsFrame.vue'
import {departments,saveDepartment,deleteDepartment,treeRows} from '@/api/organization'
const rows=ref([]),loading=ref(false),saving=ref(false),visible=ref(false),showSearch=ref(true),keyword=ref(''),status=ref(''),form=reactive({}),formRef=ref()
const rules={deptName:[{required:true,message:'请输入部门名称',trigger:'blur'}]}
const filtered=computed(()=>{const keep=nodes=>nodes.flatMap(n=>{const children=keep(n.children);return children.length||((!keyword.value||n.deptName.includes(keyword.value))&&(!status.value||n.status===status.value))?[{...n,children}]:[]});return keep(treeRows(rows.value))})
const parentTree=computed(()=>[{value:0,label:'顶级部门',children:convert(treeRows(rows.value))}])
function convert(nodes,blocked=false){return nodes.map(n=>({...n,value:n.deptId,disabled:blocked||n.deptId===form.deptId,children:convert(n.children,blocked||n.deptId===form.deptId)}))}
async function load(){loading.value=true;try{rows.value=(await departments()).data}finally{loading.value=false}}
function open(row,parentId=0){Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,{parentId,deptName:'',orderNum:0,leader:'',phone:'',email:'',status:'0'},row?{...row}:{});visible.value=true}
async function save(){if(!await formRef.value.validate().catch(()=>false))return;saving.value=true;try{await saveDepartment(form);visible.value=false;ElMessage.success('部门已保存');await load()}catch(e){console.error(e)}finally{saving.value=false}}
async function remove(row){try{await ElMessageBox.confirm(`确认删除部门“${row.deptName}”？`,'提示',{type:'warning'});await deleteDepartment(row.deptId);ElMessage.success('部门已删除');await load()}catch(e){if(e!=='cancel'&&e!=='close')console.error(e)}}
onMounted(load)
</script>
